Repair the source below and return one corrected complete TypeScript source file, preserving its exported API. `MemberDirectory` snapshots all constructor input, rejects duplicate IDs with `RangeError`, and requires `currentId` to identify an existing member. `query(options?)` filters by optional state and verified flag, then by an optional trimmed, case-insensitive search substring across handle, email, givenName, and familyName. An empty search applies no search filter. Results are sorted by ascending numeric ID before pagination. `offset` defaults to 0 and `limit` to 50; both must be safe integers, offset must be nonnegative, and limit must be from 1 through 100. `get(id)` and `current()` throw `RangeError` when unavailable. Every returned member is a fresh object, returned arrays are fresh, and neither options nor constructor inputs are mutated.

```ts
export enum MembershipState {
  Active = "active",
  Suspended = "suspended",
  Invited = "invited",
}

export interface Member {
  id: number;
  handle: string;
  email: string;
  givenName: string;
  familyName: string;
  state: MembershipState;
  verified: boolean;
  zone: string;
}

export interface MemberQuery {
  state?: MembershipState;
  search?: string;
  verified?: boolean;
  limit?: number;
  offset?: number;
}

export class MemberDirectory {
  private readonly members: Member[];

  constructor(source: readonly Member[], private readonly currentId: number) {
    const seen = new Set<number>();
    this.members = source.map((member) => {
      if (seen.has(member.id)) throw new RangeError("duplicate member id");
      seen.add(member.id);
      return { ...member };
    });
    if (!seen.has(currentId)) throw new RangeError("current member not found");
  }

  query(options: MemberQuery = {}): Member[] {
    const offset = options.offset ?? 0;
    const limit = options.limit ?? 50;
    validatePage(offset, limit);
    const search = options.search?.trim().toLocaleLowerCase() ?? "";

    return this.members
      .filter((member) => options.state === undefined || member.state === options.state)
      .filter((member) => options.verified === undefined || member.verified === options.verified)
      .filter((member) => search.length === 0 || [
        member.handle, member.email, member.givenName, member.familyName,
      ].some((value) => value.toLocaleLowerCase().includes(search)))
      .sort((a, b) => a.id - b.id)
      .slice(offset, limit)
      .map((member) => ({ ...member }));
  }

  get(id: number): Member {
    const member = this.members.find((candidate) => candidate.id === id);
    if (!member) throw new RangeError("member not found");
    return { ...member };
  }

  current(): Member {
    return this.get(this.currentId);
  }
}

function validatePage(offset: number, limit: number): void {
  if (!Number.isSafeInteger(offset) || offset < 0) throw new TypeError("invalid offset");
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100) {
    throw new TypeError("invalid limit");
  }
}
