import { MemberDirectory, MembershipState, type Member, type MemberQuery } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsKind(fn: () => unknown, kind: "TypeError" | "RangeError", message: string): void {
  try { fn(); } catch (error) {
    if ((kind === "TypeError" && error instanceof TypeError) || (kind === "RangeError" && error instanceof RangeError)) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const source: Member[] = [
  { id: 30, handle: "gamma", email: "g@example.com", givenName: "Grace", familyName: "Hopper", state: MembershipState.Suspended, verified: true, zone: "west" },
  { id: 10, handle: "alpha", email: "a@example.com", givenName: "Ada", familyName: "Lovelace", state: MembershipState.Active, verified: true, zone: "east" },
  { id: 20, handle: "beta", email: "b@example.com", givenName: "Alan", familyName: "Turing", state: MembershipState.Active, verified: false, zone: "north" },
  { id: 40, handle: "delta", email: "DELTA@example.com", givenName: "Katherine", familyName: "Johnson", state: MembershipState.Invited, verified: true, zone: "south" },
];
const original = JSON.parse(JSON.stringify(source));
const directory = new MemberDirectory(source, 20);
source[0].handle = "mutated";
source.pop();
equal(directory.query().map((member) => member.id), [10, 20, 30, 40], "constructor snapshots and results sort by ID");
equal(original[0].handle, "gamma", "test baseline remains valid");

equal(directory.query({ state: MembershipState.Active }).map((member) => member.id), [10, 20], "state filter");
equal(directory.query({ verified: true }).map((member) => member.id), [10, 30, 40], "verified filter");
equal(directory.query({ search: "  ADA  " }).map((member) => member.id), [10], "trimmed case-insensitive handle search");
equal(directory.query({ search: "EXAMPLE.COM", verified: true }).map((member) => member.id), [10, 30, 40], "email search combined with verified filter");
equal(directory.query({ search: "tur" }).map((member) => member.id), [20], "family-name substring search");
equal(directory.query({ search: "ther" }).map((member) => member.id), [40], "given-name substring search");
equal(directory.query({ search: "   " }).map((member) => member.id), [10, 20, 30, 40], "empty trimmed search applies no filter");

const pageOptions: MemberQuery = { offset: 1, limit: 2, state: MembershipState.Active };
const optionsBefore = JSON.stringify(pageOptions);
equal(directory.query(pageOptions).map((member) => member.id), [20], "pagination occurs after filtering and sorting");
equal(JSON.stringify(pageOptions), optionsBefore, "query options are not mutated");
equal(directory.query({ offset: 1, limit: 2 }).map((member) => member.id), [20, 30], "slice uses limit as count");
equal(directory.query({ offset: 99, limit: 10 }), [], "offset beyond results");

const fetched = directory.get(10);
const current = directory.current();
equal(current.id, 20, "current member");
fetched.handle = "changed";
current.email = "changed";
equal(directory.get(10).handle, "alpha", "get returns fresh objects");
equal(directory.current().email, "b@example.com", "current returns fresh objects");
const firstList = directory.query();
const secondList = directory.query();
assert(firstList !== secondList && firstList[0] !== secondList[0], "queries return fresh arrays and members");

throwsKind(() => new MemberDirectory([original[0], { ...original[0] }], 30), "RangeError", "duplicate IDs");
throwsKind(() => new MemberDirectory(original, 999), "RangeError", "missing current member");
throwsKind(() => directory.get(999), "RangeError", "missing get");
for (const offset of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  throwsKind(() => directory.query({ offset }), "TypeError", `invalid offset ${offset}`);
}
for (const limit of [0, 101, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  throwsKind(() => directory.query({ limit }), "TypeError", `invalid limit ${limit}`);
}
assert(directory.query({ limit: 1 }).length === 1, "minimum limit accepted");
assert(directory.query({ limit: 100 }).length === 4, "maximum limit accepted");

